import java.util.*;

public class Main {
    ListNode reverseBetween(ListNode head, int left, int right) {
        List<Integer> values = new ArrayList<>();
        for (ListNode node = head; node != null; node = node.next) values.add(node.val);   // collect every value into a plain list
        Collections.reverse(values.subList(left - 1, right));                                // reverse only the specified sub-range
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        for (int v : values) {
            cur.next = new ListNode(v);                                                        // rebuild a brand new list from the modified values
            cur = cur.next;
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
        ListNode result = solution.reverseBetween(head, 2, 4);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

