import java.util.*;

public class Main {
    ListNode reverseBetween(ListNode head, int left, int right) {
        ListNode dummy = new ListNode(0, head);
        ListNode prev = dummy;
        for (int i = 0; i < left - 1; i++) {
            prev = prev.next;                                                       // walk to the node just before the sub-range begins
        }

        ListNode curr = prev.next;                                                   // curr stays fixed as the sub-range's (shrinking) tail
        for (int i = 0; i < right - left; i++) {
            ListNode next = curr.next;
            curr.next = next.next;                                                     // detach the node right after curr
            next.next = prev.next;                                                     // insert it at the very front of the sub-range
            prev.next = next;
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
        ListNode result = solution.reverseBetween(head, 2, 4);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

